; EXODUS.BIN: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; WORLD: moons, moon gates, creatures, start-up (207D-259E).
;
; The world turn on the surface and in towns, and the start-up. Entry points:
;   SaveSosaria, SaveParty   write SOSARIA.ULT (with the party) and
;                  PARTY.ULT
;   AdvanceMoons          one step of the two moons: move the moon gate, make
;                  Dawn appear and vanish, print the phases on the top line
;   Whirlpool          a whirlpool takes the frigate: Sosaria -> Ambrosia,
;                  and back from Ambrosia
;   MonTurn          the creatures' turn after each command (MainLoop jumps
;                  here): MoveMonsters, SpawnMonster, BuildView, then back to the key loop
;   StartUp        the program's entry (24C4): load the files, seed the random numbers
; Data: the creature slots MonTile, MonUnder (the map byte under the creature), MonX, MonY,
; MonTalk (high bits: how it moves); the moons (Moon1Phase ...); MapWraps and the five
; tiles around the party (TileEast-TileHere) that BuildView fills.
; StartUp's memory (24C4-2581) is reused once it has run: as ViewTiles (the 11 x 11 view) and
; as the buffer for the combat maps and pictures (docs/FORMATS.md 9). ViewCell31, ViewCell3B and ViewCell45 are
; labels on start-up instructions that BuildView uses as view cells 31h, 3Bh and 45h.

CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN StackArea:BYTE
EXTRN CursorCol:BYTE
EXTRN RandState:BYTE
EXTRN RandMonthDay:BYTE
EXTRN RandHourMin:BYTE
EXTRN RandSecHund:BYTE
EXTRN RandYear2:BYTE
EXTRN RandMonthDay2:BYTE
EXTRN RandHourMin2:BYTE
EXTRN RandSecHund2:BYTE
EXTRN TileGfx:BYTE
EXTRN CharGfx:BYTE
EXTRN PutChar:NEAR
EXTRN Random:NEAR
EXTRN PrintDigit:NEAR
EXTRN SaveFile:NEAR
EXTRN LoadFile:NEAR
EXTRN SignStep:NEAR
EXTRN DrawView:NEAR
EXTRN ViewTileAt:NEAR
EXTRN WindUpdate:NEAR
EXTRN SoundOn:BYTE
EXTRN Sound:NEAR
EXTRN MapBuf:BYTE
EXTRN DawnCell:BYTE
EXTRN MonTile:BYTE
EXTRN MonUnder:BYTE
EXTRN MonX:BYTE
EXTRN MonY:BYTE
EXTRN MonTalk:BYTE
EXTRN WhirlpoolX:BYTE
EXTRN WhirlpoolY:BYTE
EXTRN Moon1Phase:BYTE
EXTRN Moon2Phase:BYTE
EXTRN Moon1Count:BYTE
EXTRN Moon2Count:BYTE
EXTRN PartyTile:BYTE
EXTRN Location:BYTE
EXTRN PartyXY:BYTE
EXTRN PlayerXY:BYTE
EXTRN PlayerY:BYTE
EXTRN LightOn:BYTE
EXTRN TimeStop:BYTE
EXTRN RideToggle:BYTE
EXTRN LastKey:BYTE
EXTRN FilePartyUlt:BYTE
EXTRN FileSosariaUlt:BYTE
EXTRN FileAmbrosiaUlt:BYTE
EXTRN GateXTbl:BYTE
EXTRN GateYTbl:BYTE
EXTRN ArrowKeys:BYTE
EXTRN SpawnTiles:BYTE
EXTRN SpawnMoves:BYTE
EXTRN MsgWhirlpool:BYTE
EXTRN MsgIntoDarkness:BYTE
EXTRN MsgForgottenLand:BYTE
EXTRN MsgAllIsDark:BYTE
EXTRN MsgYouMadeIt:BYTE
EXTRN ReadCommand:NEAR
EXTRN ReadCommandNoView:NEAR
EXTRN PrintMsg:NEAR
EXTRN ScrollMsg:NEAR
EXTRN DrawFrame:NEAR
EXTRN BuildView:NEAR
EXTRN ClearView:NEAR
EXTRN MapCellAddr:NEAR
EXTRN MonStepToPlayer:NEAR
EXTRN WhirlpoolTick:BYTE
EXTRN FlushKeys:NEAR
EXTRN StatusLine:NEAR
EXTRN DrawPlayerNums:NEAR
EXTRN FindMonster:NEAR
EXTRN DamageParty:NEAR
EXTRN FightCreature:NEAR
PUBLIC SaveSosaria
PUBLIC SaveParty
PUBLIC AdvanceMoons
PUBLIC Whirlpool
PUBLIC MonTurn
PUBLIC MapWraps
PUBLIC StartUp
PUBLIC ViewCell31
PUBLIC ViewCell3B
PUBLIC ViewCell45
PUBLIC TileEast
PUBLIC TileWest
PUBLIC TileNorth
PUBLIC TileSouth
PUBLIC TileHere
PUBLIC ViewTiles
PUBLIC CombatPartyX
PUBLIC CombatPartyY
PUBLIC CombatUnderTile
PUBLIC CombatPartyTile
;------------------------------------------------------------------------------
; SaveSosaria: write the map buffer to SOSARIA.ULT (1228h bytes, with the
; creature slots and the moons), then the party (SaveParty). Before entering a town or dungeon,
; on Quit, and when a whirlpool takes the party. Uses: nothing (saves all).
;------------------------------------------------------------------------------
SaveSosaria:	push ax	;@207D
	push bx	;@207E
	push cx	;@207F
	push dx	;@2080
	lea bx, MapBuf	;@2081
	mov cx, 1228h	;@2085
	lea dx, FileSosariaUlt	;@2088
	call SaveFile	; write the file (FCB, DOS sequential write)	;@208C
	call SaveParty	;@208F
	pop dx	;@2092
	pop cx	;@2093
	pop bx	;@2094
	pop ax	;@2095
	ret	;@2096
;------------------------------------------------------------------------------
; SaveParty: write PARTY.ULT (the 18-byte header and the four characters,
; 112h bytes from PartyTile). Uses: nothing (saves all).
;------------------------------------------------------------------------------
SaveParty:	push ax	;@2097
	push bx	;@2098
	push cx	;@2099
	push dx	;@209A
	lea bx, PartyTile	;@209B
	mov cx, 112h	;@209F
	lea dx, FilePartyUlt	;@20A2
	call SaveFile	;@20A6
	pop dx	;@20A9
	pop cx	;@20AA
	pop bx	;@20AB
	pop ax	;@20AC
	ret	;@20AD
;------------------------------------------------------------------------------
; AdvanceMoons: on Sosaria (Location 0), one step of the moons: moon 1
; changes phase every 12 steps, moon 2 every 4 (docs/FORMATS.md 3). When moon 2 changes, the
; moon gate moves: the cell for the old moon 1 phase becomes grass, the one for the new phase
; a gate (88h). At the same time the town of Dawn (map cell 37, 53) appears when both old
; phases were 7 and turns to forest when both were 0. Everywhere: print "(m1)(m2)" between the
; moon symbols at the top of the screen (row 0, column 8). Uses: nothing (saves all).
;------------------------------------------------------------------------------
AdvanceMoons:	pushf	;@20AE
	push ax	;@20AF
	push bx	;@20B0
	push dx	;@20B1
	cmp byte ptr Location, 0	;@20B2
	jne Moons_Print	;@20B7
	push word ptr Moon1Phase	; the old phases: DL = moon 1, DH = moon 2	;@20B9
	dec byte ptr Moon1Count	;@20BD
	jns Moons_Moon2	;@20C1
	mov byte ptr Moon1Count, 0Bh	; 12 steps a phase	;@20C3
	inc byte ptr Moon1Phase	;@20C8
	and byte ptr Moon1Phase, 7	;@20CC
Moons_Moon2:	dec byte ptr Moon2Count	;@20D1
	jns Moons_Gate	;@20D5
	mov byte ptr Moon2Count, 3	; 4 steps a phase	;@20D7
	inc byte ptr Moon2Phase	;@20DC
	and byte ptr Moon2Phase, 7	;@20E0
Moons_Gate:	pop dx	;@20E5
	cmp dh, byte ptr Moon2Phase	; moon 2 unchanged: the gate stays	;@20E6
	je Moons_Print	;@20EA
	mov bl, dl	; the gate of the old moon 1 phase ...	;@20EC
	mov bh, 0	;@20EE
	mov al, byte ptr GateYTbl[bx]	;@20F0
	mov bl, byte ptr GateXTbl[bx]	;@20F4
	mov bh, al	;@20F8
	call MapCellAddr	;@20FA
	mov byte ptr [bx], 4	; ... back to grass	;@20FD
	mov bl, byte ptr Moon1Phase	; the gate of the new phase	;@2100
	mov bh, 0	;@2104
	mov al, byte ptr GateYTbl[bx]	;@2106
	mov bl, byte ptr GateXTbl[bx]	;@210A
	mov bh, al	;@210E
	call MapCellAddr	;@2110
	mov byte ptr [bx], 88h	; moon gate (shape 34)	;@2113
	mov al, dl	; both old phases 7:	;@2116
	and al, dh	;@2118
	cmp al, 7	;@211A
	jne Moons_DawnGone	;@211C
	mov byte ptr DawnCell, 18h	; Dawn (37, 53) appears: Towne (shape 6)	;@211E
	jmp short Moons_Print	;@2123
Moons_DawnGone:	or dl, dh	; both old phases 0:	;@2125
	jne Moons_Print	;@2127
	mov byte ptr DawnCell, 0Ch	; Dawn vanishes: forest (shape 3)	;@2129
Moons_Print:	mov dx, 8	; row 0, column 8	;@212E
	xchg word ptr CursorCol, dx	;@2131
	mov al, 10h	; a moon symbol	;@2135
	call PutChar	;@2137
	mov al, 28h	; '('	;@213A
	call PutChar	;@213C
	mov al, byte ptr Moon1Phase	;@213F
	call PrintDigit	;@2142
	mov al, 29h	; ')'	;@2145
	call PutChar	;@2147
	mov al, 28h	;@214A
	call PutChar	;@214C
	mov al, byte ptr Moon2Phase	;@214F
	call PrintDigit	;@2152
	mov al, 29h	;@2155
	call PutChar	;@2157
	mov al, 11h	; the other moon symbol	;@215A
	call PutChar	;@215C
	mov word ptr CursorCol, dx	;@215F
	pop dx	;@2163
	pop bx	;@2164
	pop ax	;@2165
	popf	;@2166
	ret	;@2167
;------------------------------------------------------------------------------
; Whirlpool: the party in its frigate stands on a whirlpool (MainLoop, and
; PARTY 73E7 when the whirlpool runs into the party). "A huge swirling --WhirlPool-- engulfs
; you ...". On Sosaria: the frigate is lost, the whirlpool restarts at x 3, a random y; the
; world is saved; then AMBROSIA.ULT is loaded (the moon phases kept), the party on foot at
; (32, 54), Location 0FFh. In Ambrosia: "All is Dark!", SOSARIA.ULT is loaded again, the party
; back at its saved place, in a frigate, "You made it!", Location 0.
; Uses: nothing (saves all).
;------------------------------------------------------------------------------
Whirlpool:	pushf	;@2168
	push ax	;@2169
	push bx	;@216A
	push cx	;@216B
	push dx	;@216C
	push si	;@216D
	mov byte ptr PartyTile, 0Ch	; draw the party as a whirlpool	;@216E
	call BuildView	;@2173
	mov byte ptr PartyTile, 0Bh	; frigate again	;@2176
	lea si, MsgWhirlpool	;@217B
	call PrintMsg	;@217F
	mov al, 0F4h	; sound 0F4h	;@2182
	call Sound	;@2184
	cmp byte ptr Location, 0FFh	; in Ambrosia already	;@2187
	je Whirlpool_Back	;@218C
	mov bx, word ptr PlayerXY	;@218E
	mov word ptr PartyXY, bx	; remember where the party was	;@2192
	call MapCellAddr	;@2196
	mov byte ptr [bx], 0	; the frigate is lost: water	;@2199
	mov dh, 37h	; a new place for the whirlpool: y = 7-3Dh, x = 3	;@219C
	call Random	;@219E
	add dl, 7	;@21A1
	mov byte ptr WhirlpoolX, 3	; WhirlpoolX/WhirlpoolY are really the whirlpool's x and y (PARTY 736C)	;@21A4
	mov byte ptr WhirlpoolY, dl	;@21A9
	call SaveSosaria	; save Sosaria and the party	;@21AD
	call ClearView	;@21B0
	lea si, MsgIntoDarkness	;@21B3
	call PrintMsg	;@21B7
	push word ptr Moon1Phase	;@21BA
	lea bx, MapBuf	;@21BE
	mov cx, 1228h	;@21C2
	lea dx, FileAmbrosiaUlt	;@21C5
	call LoadFile	; the moons' phases are kept	;@21C9
	pop word ptr Moon1Phase	;@21CC
	mov byte ptr PartyTile, 3Fh	; on foot	;@21D0
	mov word ptr PlayerXY, 3620h	; x 32, y 54	;@21D5
	mov byte ptr Location, 0FFh	; Ambrosia	;@21DB
	lea si, MsgForgottenLand	;@21E0
	call PrintMsg	;@21E4
	call BuildView	;@21E7
Whirlpool_Done:	call FlushKeys	;@21EA
	pop si	;@21ED
	pop dx	;@21EE
	pop cx	;@21EF
	pop bx	;@21F0
	pop ax	;@21F1
	popf	;@21F2
	ret	;@21F3
Whirlpool_Back:	lea si, MsgAllIsDark	; "All is Dark!"	;@21F4
	call PrintMsg	;@21F8
	call ClearView	;@21FB
	lea bx, MapBuf	;@21FE
	mov cx, 1228h	;@2202
	lea dx, FileSosariaUlt	;@2205
	call LoadFile	;@2209
	lea si, MsgYouMadeIt	; "You made it!"	;@220C
	call PrintMsg	;@2210
	mov ax, word ptr PartyXY	;@2213
	mov word ptr PlayerXY, ax	;@2216
	mov byte ptr Location, 0	;@2219
	mov byte ptr PartyTile, 0Bh	; in a frigate again	;@221E
	call SaveParty	;@2223
	jmp Whirlpool_Done	;@2226
;------------------------------------------------------------------------------
; MonCanEnter: may the creature in slot SI step on the cell at DX (DL = x, DH = y), whose map
; byte is AL? Sea creatures (tiles 2Ch-3Fh: serpent, man-o-war, pirate) need water; the others
; grass, brush, forest or floor; and no other creature may stand there.
; Out: AL = 0FFh yes, 0 no. Uses: nothing else.
;------------------------------------------------------------------------------
MonCanEnter:	pushf	;@2228
	push bx	;@2229
	cmp byte ptr MonTile[si], 4	; tile 4 (grass) as a creature: only onto its own kind (never happens?)	;@222A
	jne MonCanEnter_TrySea	;@222F
	cmp al, byte ptr MonTile[si]	;@2231
	jmp short MonCanEnter_Test	;@2235
MonCanEnter_TrySea:	cmp byte ptr MonTile[si], 40h	; sea creatures: 2Ch-3Fh	;@2237
	jae MonCanEnter_Land	;@223C
	cmp byte ptr MonTile[si], 2Ch	;@223E
	jb MonCanEnter_Land	;@2243
	cmp al, 0	; water only	;@2245
MonCanEnter_Test:	je MonCanEnter_Free	;@2247
	jmp short MonCanEnter_No	;@2249
MonCanEnter_Land:	cmp al, 4	; grass	;@224B
	je MonCanEnter_Free	;@224D
	cmp al, 8	; brush	;@224F
	je MonCanEnter_Free	;@2251
	cmp al, 0Ch	; forest	;@2253
	je MonCanEnter_Free	;@2255
	cmp al, 20h	; floor	;@2257
	jne MonCanEnter_No	;@2259
MonCanEnter_Free:	mov al, 0FFh	; is a creature at DX? (BX = slot, or -1)	;@225B
	call FindMonster	;@225D
	cmp bx, -1	;@2260
	jne MonCanEnter_No	;@2263
MonCanEnter_Done:	pop bx	;@2265
	popf	;@2266
	ret	;@2267
MonCanEnter_No:	mov al, 0	;@2268
	jmp MonCanEnter_Done	;@226A
;------------------------------------------------------------------------------
; MonTurn: the rest of a turn, jumped to by MainLoop. On a horse or in a
; frigate the creatures move only every other step while the party moves with the arrow keys
; (RideToggle flips between 1 and -1; any other command resets it). While Negate Time's counter
; (TimeStop) runs they do not move at all. Then BuildView and back to the key loop (ReadCommandNoView).
;------------------------------------------------------------------------------
MonTurn:	cmp byte ptr PartyTile, 3Fh	; on foot: the creatures always move	;@226C
	je MonTurn_Clock	;@2271
	mov ax, word ptr LastKey	; the last command's key word (LastKey)	;@2273
	mov cx, 4	;@2276
	lea di, ArrowKeys	; the four arrow keys	;@2279
	repne scasw	;@227D
	je MonTurn_Toggle	;@227F
	mov byte ptr RideToggle, 0FFh	; not an arrow: move this time	;@2281
MonTurn_Toggle:	neg byte ptr RideToggle	; 1 -> -1 -> 1 ...: skip every other step	;@2286
	js MonTurn_Draw	;@228A
MonTurn_Clock:	test byte ptr TimeStop, 0FFh	;@228C
	je MonTurn_Move	;@2291
	dec byte ptr TimeStop	; Negate Time: frozen	;@2293
	jmp short MonTurn_Draw	;@2297
MonTurn_Move:	call MoveMonsters	;@2299
	call SpawnMonster	;@229C
MonTurn_Draw:	call BuildView	;@229F
	jmp ReadCommandNoView	;@22A2
;------------------------------------------------------------------------------
; SpawnMonster: on Sosaria only, with a chance of 7 in 135 a step, put a new creature in a free
; slot: a kind from the 13 of SpawnTiles (two random numbers ANDed: the first kinds are the most
; common), at a random place not in the party's row or column, and only if the cell there is
; the creature's ground (SpawnMoves: grass for land creatures, water for the sea ones). It is hostile
; (MonTalk 0C0h). Uses: nothing (saves all).
;------------------------------------------------------------------------------
SpawnMonster:	pushf	;@22A5
	push ax	;@22A6
	push bx	;@22A7
	push cx	;@22A8
	push dx	;@22A9
	push si	;@22AA
	cmp byte ptr Location, 0	;@22AB
	jne Spawn_Done	;@22B0
	mov dh, 87h	;@22B2
	call Random	;@22B4
	shl dl, 1	; carry when DL >= 80h: 7 in 135	;@22B7
	jae Spawn_Done	;@22B9
	mov cx, 20h	;@22BB
	mov bx, 0	;@22BE
Spawn_FindSlot:	cmp byte ptr MonTile[bx], 0	;@22C1
	je Spawn_Slot	;@22C6
	inc bx	;@22C8
	loop Spawn_FindSlot	;@22C9
Spawn_Done:	pop si	;@22CB
	pop dx	;@22CC
	pop cx	;@22CD
	pop bx	;@22CE
	pop ax	;@22CF
	popf	;@22D0
	ret	;@22D1
Spawn_Slot:	mov dh, 0Dh	; the kind: rnd(13) AND rnd(13)	;@22D2
	call Random	;@22D4
	mov al, dl	;@22D7
	call Random	;@22D9
	and dl, al	;@22DC
	mov si, bx	;@22DE
	mov bl, dl	;@22E0
	mov al, byte ptr SpawnTiles[bx]	; its tile	;@22E2
	mov ah, byte ptr SpawnMoves[bx]	; its ground (4 grass, 0 water)	;@22E6
	mov byte ptr MonTile[si], al	;@22EA
	mov byte ptr MonUnder[si], ah	; kept as the byte under it	;@22EE
	mov dh, 40h	;@22F2
	call Random	;@22F4
	cmp dl, byte ptr PlayerXY	; not in the party's column	;@22F7
	je Spawn_Fail	;@22FB
	mov bl, dl	;@22FD
	call Random	;@22FF
	cmp dl, byte ptr PlayerY	; nor in its row (PlayerY = the party's y)	;@2302
	je Spawn_Fail	;@2306
	mov bh, dl	;@2308
	mov byte ptr MonX[si], bl	;@230A
	mov byte ptr MonY[si], bh	;@230E
	mov byte ptr MonTalk[si], 0C0h	; hostile: moves towards the party and attacks	;@2312
	call MapCellAddr	;@2317
	cmp al, byte ptr MonUnder[si]	; only on its own ground	;@231A
	jne Spawn_Fail	;@231E
	mov al, byte ptr MonTile[si]	;@2320
	mov byte ptr [bx], al	; put it on the map	;@2324
	jmp Spawn_Done	;@2326
Spawn_Fail:	mov byte ptr MonTile[si], 0	; no place: the slot stays free	;@2328
	jmp Spawn_Done	;@232D
;------------------------------------------------------------------------------
; MonShoot: the creature in slot SI (a dragon or a pirate) fires at the party, one time in
; two, if it is inside the view: a fire bolt (shape 3Dh) flies up to three cells towards the
; party, stopped by mountains, walls and void; if it reaches the party's cell DamageParty hurts the
; party (?). Uses: nothing (saves all).
;------------------------------------------------------------------------------
MonShoot:	pushf	;@232F
	push ax	;@2330
	push bx	;@2331
	push cx	;@2332
	push dx	;@2333
	mov dh, 0FFh	;@2334
	call Random	;@2336
	shl dl, 1	; one time in two	;@2339
	jb MonShoot_Done	;@233B
	call MonStepToPlayer	; CL, CH = the step towards the party	;@233D
	mov bx, 505h	; BH = view row, BL = view column of the creature	;@2340
	sub bh, byte ptr PlayerY	;@2343
	add bh, byte ptr MonY[si]	;@2347
	cmp bh, 0Bh	;@234B
	jae MonShoot_Done	;@234E
	sub bl, byte ptr PlayerXY	;@2350
	add bl, byte ptr MonX[si]	;@2354
	cmp bl, 0Bh	;@2358
	jae MonShoot_Done	;@235B
	call BuildView	;@235D
	mov al, 0FBh	; sound 0FBh	;@2360
	call Sound	;@2362
	mov dx, bx	;@2365
	mov ah, 3	; three cells at most	;@2367
MonShoot_Step:	add dh, ch	;@2369
	cmp dh, 0Bh	; 0Bh is let through: one past the view (harmless?)	;@236B
	ja MonShoot_Done	;@236E
	add dl, cl	;@2370
	cmp dl, 0Bh	;@2372
	ja MonShoot_Done	;@2375
	mov bx, dx	;@2377
	call ViewTileAt	; AL = the tile, BX = its place in ViewTiles	;@2379
	cmp al, 4	; mountains	;@237C
	je MonShoot_Done	;@237E
	cmp al, 23h	; wall	;@2380
	je MonShoot_Done	;@2382
	cmp al, 24h	; void	;@2384
	je MonShoot_Done	;@2386
	mov byte ptr [bx], 3Dh	; draw the bolt (Fire)	;@2388
	call DrawView	;@238B
	mov byte ptr [bx], al	;@238E
	cmp dx, 505h	; the party's cell	;@2390
	jne MonShoot_Next	;@2394
	call DamageParty	;@2396
	jmp short MonShoot_Done	;@2399
MonShoot_Next:	dec ah	;@239B
	jne MonShoot_Step	;@239D
MonShoot_Done:	pop dx	;@239F
	pop cx	;@23A0
	pop bx	;@23A1
	pop ax	;@23A2
	popf	;@23A3
	ret	;@23A4
;------------------------------------------------------------------------------
; MoveMonsters: move every creature slot (31 down to 0) one step. On Sosaria all chase the
; party, and one that would step on it starts a fight (FightCreature, slot in BX; this routine and its
; caller are dropped from the stack). In a town the two high bits of MonTalk say how it moves:
; 0 stands, 1 wanders at random (half the time), 2 approaches the party, 3 chases and attacks
; as on Sosaria. The creature tries the diagonal step, then the vertical, then the horizontal
; one. Dragons (74h) and pirates (3Ch) also fire (MonShoot), moving or not.
; Uses: nothing (saves all).
;------------------------------------------------------------------------------
MoveMonsters:	push bp	;@23A5
	mov bp, sp	;@23A6
	pushf	;@23A8
	push ax	;@23A9
	push bx	;@23AA
	push cx	;@23AB
	push dx	;@23AC
	push si	;@23AD
	mov si, 1Fh	; slot 31 first	;@23AE
MoveMon_Slot:	cmp byte ptr MonTile[si], 0	;@23B1
	jne MoveMon_Active	;@23B6
MoveMon_Skip:	jmp MoveMon_Next	;@23B8
MoveMon_Active:	cmp byte ptr Location, 0	;@23BB
	jne MoveMon_Town	;@23C0
MoveMon_Chase:	call MonStepToPlayer	; DX = one step towards the party, CL/CH = the step	;@23C2
	cmp dx, word ptr PlayerXY	;@23C5
	jne MoveMon_Try	;@23C9
	lea sp, [bp+4]	; drop the saved registers and the return to MonTurn	;@23CB
	mov bx, si	;@23CE
	jmp FightCreature	; the creature attacks: the fight	;@23D0
MoveMon_Town:	mov al, byte ptr MonTalk[si]	; the kind bits	;@23D3
	and al, 0C0h	;@23D7
	mov cl, 6	;@23D9
	shr al, cl	;@23DB
	cmp al, 0	;@23DD
	je MoveMon_Skip	; 0: stands	;@23DF
	cmp al, 1	;@23E1
	je MoveMon_Wander	;@23E3
	cmp al, 3	;@23E5
	je MoveMon_Chase	; 3: hostile	;@23E7
	call MonStepToPlayer	; 2: approaches (never attacks: MoveMon_Go refuses the party's cell)	;@23E9
	jmp short MoveMon_Try	;@23EC
MoveMon_Wander:	mov dh, 0FFh	; 1: wanders, half the time	;@23EE
	call Random	;@23F0
	shl dl, 1	;@23F3
	jae MoveMon_Skip	;@23F5
	call Random	;@23F7
	mov al, dl	;@23FA
	call SignStep	; AH = -1, 0 or +1	;@23FC
	mov cl, ah	;@23FF
	mov dl, byte ptr MonX[si]	;@2401
	add dl, cl	;@2405
	and dl, 3Fh	; x 0 is the town's edge: stay	;@2407
	je MoveMon_Skip	;@240A
	mov bx, dx	;@240C
	call Random	;@240E
	mov al, dl	;@2411
	call SignStep	;@2413
	mov dx, bx	;@2416
	mov ch, ah	;@2418
	mov dh, byte ptr MonY[si]	;@241A
	add dh, ch	;@241E
	and dh, 3Fh	;@2420
	je MoveMon_Skip	; y 0 likewise	;@2423
MoveMon_Try:	mov bx, dx	; the diagonal step	;@2425
	call MapCellAddr	;@2427
	call MonCanEnter	;@242A
	cmp al, 0FFh	;@242D
	je MoveMon_Go	;@242F
	mov dl, byte ptr MonX[si]	; the vertical step	;@2431
	mov bx, dx	;@2435
	call MapCellAddr	;@2437
	call MonCanEnter	;@243A
	cmp al, 0FFh	;@243D
	je MoveMon_Go	;@243F
	add dl, cl	; the horizontal step	;@2441
	and dl, 3Fh	;@2443
	mov dh, byte ptr MonY[si]	;@2446
	mov bx, dx	;@244A
	call MapCellAddr	;@244C
	call MonCanEnter	;@244F
	cmp al, 0FFh	;@2452
	je MoveMon_Go	;@2454
	cmp byte ptr MonTile[si], 74h	; cannot move: a dragon ...	;@2456
	je MoveMon_Shoot	;@245B
	cmp byte ptr MonTile[si], 3Ch	; ... or a pirate fires anyway	;@245D
	jne MoveMon_Skip2	;@2462
MoveMon_Shoot:	call MonShoot	;@2464
MoveMon_Skip2:	jmp short MoveMon_Next	;@2467
MoveMon_Go:	cmp dx, word ptr PlayerXY	; never onto the party	;@2469
	je MoveMon_Next	;@246D
	mov bh, byte ptr MonY[si]	;@246F
	mov bl, byte ptr MonX[si]	;@2473
	call MapCellAddr	;@2477
	mov al, byte ptr MonUnder[si]	; the old cell gets back the byte under the creature	;@247A
	mov byte ptr [bx], al	;@247E
	mov byte ptr MonY[si], dh	;@2480
	mov byte ptr MonX[si], dl	;@2484
	mov bx, dx	;@2488
	call MapCellAddr	;@248A
	mov byte ptr MonUnder[si], al	; remember the byte under the new cell	;@248D
	mov al, byte ptr MonTile[si]	;@2491
	mov byte ptr [bx], al	; and draw the creature there	;@2495
	cmp byte ptr MonTile[si], 74h	;@2497
	je MoveMon_Shoot	;@249C
	cmp byte ptr MonTile[si], 3Ch	;@249E
	je MoveMon_Shoot	;@24A3
MoveMon_Next:	dec si	;@24A5
	js MoveMon_Done	;@24A6
	jmp MoveMon_Slot	;@24A8
MoveMon_Done:	pop si	;@24AB
	pop dx	;@24AC
	pop cx	;@24AD
	pop bx	;@24AE
	pop ax	;@24AF
	popf	;@24B0
	pop bp	;@24B1
	ret	;@24B2
	db 0h,0h,0h,0h,0h,0h,0h,0h,0h,0h,0h,0h,0h	; not used	;@24B3
; MapWraps: 0FFh on Sosaria and Ambrosia, where the map wraps around; 0 in a
; town or castle (CmdEnter), where BuildView shows grass outside the map. SHRINE 6463 and
; StartUp set it back.
MapWraps label byte
	db 0FFh	;@24C0
; CritErrHandler (int 24h, the DOS critical error handler): AL = 1, retry.
; CtrlBreakHandler (int 23h): Ctrl-C / Ctrl-Break are ignored.
CritErrHandler:	mov al, 1	;@24C1
CtrlBreakHandler:	iret	;@24C3
;------------------------------------------------------------------------------
; StartUp: the program's entry (EXODUS.BIN starts here through the vector at 1328). Sets the
; stack and the Ctrl-C and critical error handlers, draws the frame, loads CHARSET.ULT,
; PARTY.ULT, SOSARIA.ULT and SHAPES.ULT, places the party at its saved position, sets the
; flags (map wraps, sound on, light off, Negate Time off), seeds the random numbers from the
; time and date and enters the key loop (ReadCommand). It runs once: its memory becomes ViewTiles
; and the combat buffer (docs/FORMATS.md 9).
;------------------------------------------------------------------------------
ViewTiles label byte	;@24C4
StartUp:	lea sp, StackArea	;@24C4
	add sp, 100h	; SP = the top of the library's 256-byte stack	;@24C8
	mov ax, 0	;@24CC
	push es	;@24CF
	mov es, ax	;@24D0
	mov ax, cs	;@24D2
	mov word ptr es:[8Ch], offset CtrlBreakHandler	; int 23h vector: Ctrl-Break	;@24D4
	mov word ptr es:[8Eh], ax	;@24DB
	mov word ptr es:[90h], offset CritErrHandler	; int 24h vector: critical error	;@24DF
	mov word ptr es:[92h], ax	;@24E6
	pop es	;@24EA
	call DrawFrame	; DrawFrame	;@24EB
	lea bx, CharGfx	;@24EE
	mov cx, 800h	;@24F2
ViewCell31:	lea dx, FileCharsetUlt	; = view cell 31h (north of the party) for BuildView	;@24F5
	call LoadFile	;@24F9
	call DrawPlayerNums	;@24FC
ViewCell3B:	call WindUpdate	; = view cell 3Bh (west); +1 the party's cell, +2 east	;@24FF
	lea bx, PartyTile	;@2502
	mov cx, 112h	;@2506
ViewCell45:	lea dx, FilePartyUlt	; = view cell 45h; +2 is cell 47h (south)	;@2509
	call LoadFile	;@250D
	call StatusLine	;@2510
	lea bx, MapBuf	;@2513
	mov cx, 1228h	;@2517
	lea dx, FileSosariaUlt	;@251A
	call LoadFile	;@251E
	call AdvanceMoons	; print the moons (one moon step at each start)	;@2521
	lea bx, TileGfx	;@2524
	mov cx, 1400h	;@2528
	lea dx, FileShapesUlt	;@252B
	call LoadFile	;@252F
	mov ax, word ptr PartyXY	; the saved position	;@2532
	mov word ptr PlayerXY, ax	;@2535
	mov byte ptr MapWraps, 0FFh	; MapWraps = MapWraps	;@2538
	mov byte ptr SoundOn, 0FFh	;@253D
	mov byte ptr WhirlpoolTick, 1	; the whirlpool's step counter (PARTY 7357)	;@2542
	mov byte ptr TimeStop, 0	;@2547
	mov byte ptr LightOn, 0	;@254C
	call FlushKeys	;@2551
	mov ah, 2Ch	; DOS get time: CH hour, CL minutes, DH seconds, DL 1/100	;@2554
	int 21h	;@2556
	mov word ptr RandSecHund2, dx	; seed RandState with the time ...	;@2558
	mov word ptr RandSecHund, dx	;@255C
	mov word ptr RandHourMin2, cx	;@2560
; CombatPartyX, CombatPartyY, CombatUnderTile, CombatPartyTile (library arrays, scope lib) fall here once a combat map
; is loaded
CombatPartyX label byte	;@2564
	mov word ptr RandHourMin, cx	;@2564
CombatPartyY label byte	;@2568
	mov ah, 2Ah	; DOS get date: CX year, DH month, DL day	;@2568
	int 21h	;@256A
CombatUnderTile label byte	;@256C
	mov word ptr RandMonthDay2, dx	; ... and the date	;@256C
CombatPartyTile label byte	;@2570
	mov word ptr RandMonthDay, dx	;@2570
	mov word ptr RandYear2, cx	;@2574
	mov word ptr RandState, cx	;@2578
	call ScrollMsg	;@257C
	jmp ReadCommand	; BuildView, then the key loop	;@257F
FileCharsetUlt label byte
	db 43h,48h,41h,52h,53h,45h,54h,2Eh,55h,4Ch,54h,0h	;@2582
FileShapesUlt label byte
	db 53h,48h,41h,50h,45h,53h,2Eh,55h,4Ch,54h,0h	;@258E
; The shapes around the party, filled by BuildView: TileEast,
; TileWest, TileNorth, TileSouth, TileHere (the party's own cell).
TileEast label byte
	db 0h	;@2599
TileWest label byte
	db 0h	;@259A
TileNorth label byte
	db 0h	;@259B
TileSouth label byte
	db 0h	;@259C
TileHere label byte
	db 0h	;@259D
CODE ENDS
END
